   15         Remove-Item -Recurse -Force $Adobe -ErrorAction SilentlyContinue
   16         New-Item -ItemType SymbolicLink -Path $Adobe -Target "$Vault\CACHES\Adobe_Media_Cache" -Force | Out-Null
