   29                 { $_ -in ".jpg", ".png", ".jpeg" } { "IMAGENES" }
   30                 { $_ -in ".mp4", ".mov" } { "VIDEO" }
   31                 { $_ -in ".wav", ".mp3" } { "AUDIO" }
