   33             }
   34             $Target = Join-Path $Vault "ARCHIVOS_ORGANIZADOS\$Cat"
   35             if (!(Test-Path $Target)) { New-Item -ItemType Directory -Path $Target -Force | Out-Null }
   36             $Dest = Join-Path $Target $F.Name
   37             if (Test-Path $Dest) {
   38                 if ((Get-FileHash $Dest).Hash -eq $Hash) { Remove-Item $F.FullName -Force; continue }
   39                 $Dest = Join-Path $Target "$($F.BaseName)_$($Hash.Substring(0,4))$($F.Extension)"
   40             }
   41             Move-Item $F.FullName $Dest -Force
   42             Write-Host "✔ Migrado: $($F.Name)" -ForegroundColor Green
